"def _find_fallback_verified_sentences(
    docs_by_id: dict[str, dict[str, Any]],
    pattern: re.Pattern[str],
    *,
    doc_type: str | None = None,
    limit: int = 6,
) -> list[dict[str, Any]]:
    """Deterministically pull verbatim sentences matching `pattern` directly from PDF pages."""
    hits: list[dict[str, Any]] = []
    for doc_id, doc in docs_by_id.items():
        if doc_type and doc.get("doc_type") != doc_type:
            continue
        for pno, ptext in sorted((doc.get("pages") or {}).items()):
            norm_page = re.sub(r"\s+", " ", ptext).strip()
            for sent in re.split(r"(?<=[.!?])\s+", norm_page):
                s = sent.strip()
                if 45 <= len(s) <= 280 and pattern.search(s):
                    cit = verify_citation(
                        {"doc_id": doc_id, "page": pno, "verbatim_quote": s},
                        docs_by_id,
                    )
                    if cit.get("verified"):
                        hits.append(cit)
                        if len(hits) >= limit:
                            return hits
    return hits"

